import { z } from 'zod';

/**
 * Built-in asset manifest (FR-032): describes the CC0 art and audio shipped in
 * public/assets/builtin/. Generated by scripts/fetch-builtin-assets.ts.
 */

export const IMAGE_CATEGORIES = [
  'character',
  'enemy',
  'item',
  'ui',
  'background',
  'projectile',
  'prop',
] as const;
export const ASSET_THEMES = ['platformer', 'topdown', 'clicker', 'any'] as const;
export const SOUND_CATEGORIES = ['sfx', 'music'] as const;

export type ImageCategory = (typeof IMAGE_CATEGORIES)[number];
export type AssetTheme = (typeof ASSET_THEMES)[number];
export type SoundCategory = (typeof SOUND_CATEGORIES)[number];

const theme = z.enum(ASSET_THEMES);
const label = z.string().min(1);
const positiveInt = z.number().int().positive();

export const builtinImageSchema = z
  .object({
    /** Horizontal strip: PNG width = w * frames, height = h. */
    file: z.string().regex(/^img\/[a-z0-9_-]+\.png$/),
    w: positiveInt,
    h: positiveInt,
    frames: positiveInt,
    fps: z.number().positive(),
    category: z.enum(IMAGE_CATEGORIES),
    theme,
    name: label,
  })
  .strict();

export const builtinTilesetSchema = z
  .object({
    file: z.string().regex(/^tiles\/[a-z0-9_-]+\.png$/),
    tileSize: positiveInt,
    columns: positiveInt,
    count: positiveInt,
    solid: z.array(z.boolean()),
    oneWay: z.array(z.boolean()),
    theme,
    name: label,
  })
  .strict()
  .refine((t) => t.solid.length === t.count && t.oneWay.length === t.count, {
    message: 'solid and oneWay must have one entry per tile',
  });

export const builtinSoundSchema = z
  .object({
    file: z.string().regex(/^sfx\/[a-z0-9_-]+\.(ogg|mp3|wav)$/),
    /** Seconds. */
    duration: z.number().positive(),
    category: z.enum(SOUND_CATEGORIES),
    name: label,
  })
  .strict();

export const builtinManifestSchema = z
  .object({
    version: z.literal(1),
    images: z.record(z.string().regex(/^builtin:img\/[a-z0-9_]+$/), builtinImageSchema),
    tilesets: z.record(z.string().regex(/^builtin:tiles\/[a-z0-9_]+$/), builtinTilesetSchema),
    sounds: z.record(z.string().regex(/^builtin:(sfx|music)\/[a-z0-9_]+$/), builtinSoundSchema),
  })
  .strict();

export type BuiltinImage = z.infer<typeof builtinImageSchema>;
export type BuiltinTileset = z.infer<typeof builtinTilesetSchema>;
export type BuiltinSound = z.infer<typeof builtinSoundSchema>;
export type BuiltinManifest = z.infer<typeof builtinManifestSchema>;

/** Directory of the built-in assets relative to the app base URL. */
export const BUILTIN_ASSET_DIR = 'assets/builtin/';

/** Absolute-path base URL of the built-in assets for the running Vite app. */
export function builtinBaseUrl(): string {
  return `${import.meta.env?.BASE_URL ?? '/'}${BUILTIN_ASSET_DIR}`;
}

/** URL of a manifest entry's `file` (e.g. `img/hero.png`). */
export function builtinAssetUrl(file: string, base: string = builtinBaseUrl()): string {
  return base.endsWith('/') ? `${base}${file}` : `${base}/${file}`;
}

/** Validates raw manifest JSON; throws a ZodError when it does not match. */
export function parseBuiltinManifest(json: unknown): BuiltinManifest {
  return builtinManifestSchema.parse(json);
}

export interface LoadManifestOptions {
  /** Base URL of the asset directory; defaults to `builtinBaseUrl()`. */
  base?: string;
  fetch?: typeof fetch;
}

/** Fetches and validates `manifest.json` from the built-in asset directory. */
export async function loadManifest(options: LoadManifestOptions = {}): Promise<BuiltinManifest> {
  const doFetch = options.fetch ?? fetch;
  const url = builtinAssetUrl('manifest.json', options.base ?? builtinBaseUrl());
  const res = await doFetch(url);
  if (!res.ok) throw new Error(`Failed to load built-in asset manifest (${res.status}) from ${url}`);
  return parseBuiltinManifest(await res.json());
}
